package org.eclipse.jdt.internal.ui.text.javadoc;

import org.eclipse.jface.text.rules.IRule;
import org.eclipse.jface.text.rules.IToken;
import org.eclipse.jface.text.rules.SingleLineRule;

import java.util.ArrayList;
import java.util.List;

public class JavaDocScanner {
    IToken getToken(String constant) { return null; }

    public void configureRules() {
        List<IRule> list = new ArrayList<>();
        IToken token = getToken("JAVADOC_LINK");
        list.add(new SingleLineRule("{@link", "}", token));
        list.add(new SingleLineRule("{@value", "}", token));
        list.add(new SingleLineRule("{@inheritDoc", "}", token));
    }
}

