negativeExample:
package org.eclipse.jdt.internal.ui.text.javadoc;

import org.eclipse.jface.text.rules.IRule;
import org.eclipse.jface.text.rules.IToken;
import org.eclipse.jface.text.rules.SingleLineRule;
import org.eclipse.jface.text.rules.ICharacterScanner; // Different import for different constructor

import java.util.ArrayList;
import java.util.List;

public class JavaDocScanner {
    IToken getToken(String constant) { return null; }

    public void configureOtherRules() {
        List<IRule> list = new ArrayList<>();
        IToken otherToken = getToken("OTHER_TOKEN");
        // This constructor has a different signature and should not be matched
        list.add(new SingleLineRule("start", "end", otherToken, ICharacterScanner.EOF));
    }
}
